// Palworld breeding data for the Palworld Breeding Calculator.
//
// Matches Palworld game version 1.0.3 (cross-checked against two independent
// extracts of the game's own data files). Breeding values can change in game
// patches, so re-check this file after a Palworld update.
//
// Text only: no official images, icons or artwork are used.

export const palDataGameVersion = "1.0.3";

export type PalElement =
  | "Neutral"
  | "Fire"
  | "Water"
  | "Grass"
  | "Electric"
  | "Ice"
  | "Ground"
  | "Dark"
  | "Dragon";

export type PalGender = "male" | "female";

export type Pal = {
  /** Stable internal id used by the game. */
  id: string;
  /** English display name. */
  name: string;
  /** Paldeck number (Terraria collaboration Pals use 10000+). */
  paldeckNo: number;
  /** Elemental variant of another Pal (shown with a "B" in the Paldeck). */
  isVariant: boolean;
  /** Hidden breeding value. Lower values are rarer and stronger. */
  breedingPower: number;
  /**
   * Used when two Pals are equally close to the target breeding power:
   * the higher value wins, then the non-variant Pal.
   */
  tieBreakPriority: number;
  elements: readonly PalElement[];
  /**
   * The formula never produces this Pal. It only hatches from two parents of
   * its own species or from one of the special pairs below.
   */
  specialOnly?: true;
};

/** A fixed pair of parents that always produces a specific child. */
export type SpecialCombo = {
  parentA: string;
  parentAGender?: PalGender;
  parentB: string;
  parentBGender?: PalGender;
  child: string;
};

